% Generated by lang/prolog/tests/mkiso.py: v(Name, Expected, Goal).


v(lgt_msort_2_01, true(Sorted == [1, 1]), (msort([1, 1], Sorted))).
v(lgt_msort_2_02, true(Sorted == [1, 1, 2, 2, 3, 3]), (msort([3, 2, 1, 1, 2, 3], Sorted))).
v(lgt_msort_2_07, error(instantiation_error), (msort(_, _))).
v(lgt_msort_2_08, error(instantiation_error), (msort([a|_],_))).
v(lgt_msort_2_09, error(type_error(list,3)), (msort(3, _))).
v(lgt_msort_2_10, error(type_error(list,[a|b])), (msort([a|b],_))).
v(lgt_msort_2_11, error(type_error(list,[a,b|c])), (msort([a,b|c],_))).
v(lgt_msort_2_12, error(type_error(list,3)), (msort([], 3))).
v(lgt_msort_2_13, error(type_error(list,[a,a,b|d])), (msort([a,b,a], [a,a,b|d]))).
v(lgt_msort_2_14, false, (msort([2], [3]))).
